/* ret_nodal_api.c (linear return) - the reissue card's RETURN half as ONE linear block + two ports that vanish in the
 * linear region, behind the calls of ret_nodal_api.h (the plugin takes it by pointing FX_CARD_RET at this directory).
 *   linear: C3, R9, R2, the gain network (R5 // C2, R3, R1 | wire, C9) and the WHOLE linear op-amp from its datasheet
 *     (A0, GBW, ZO: gm into the pole node p1 with Rp, Cp, a follower + ZO to o2), generated by gen_linret_c.py
 *     (linret_circuit.h, continuous A B C D from the SymPy MNA); discretised HERE at the engine rate,
 *     x_n = Phi x + G0 u_prev + G1 u_n by Van Loan's augmented exponential (exact for the linear part; the op-amp's
 *     ~3.9 MHz loop needs no step control), the jack with a first-order hold, the port currents held at their new value
 *     over the step (a ramp on a stiff constraint rings at Nyquist);
 *   port iz: the 12 V zener pair at d (nlcore nl_dev_zener.h's law, the series pair solved at instantiate into a sweep);
 *   port ip: the output swing limit at p1, the datasheet's VOM (LR_VP): its open-circuit value is known before it (the
 *     linear op-amp is in the block), so the step is EXPLICIT - no Newton.
 * Not modelled: the input stage's slew (tanh, SR Cp): at 96 / 192 kHz the audio-band null against the full card is
 * equal or better without it.
 * No allocation after cr_ret_new; cr_ret_reset is allocation-free. */
#include <stdlib.h>
#include "linret_circuit.h"
#include "../lr_common.h"
#include "ret_nodal_api.h"

typedef struct {
    double Phi[LR_NX][LR_NX], G0j[LR_NX], G1[LR_NX][LR_NU], Cy[LR_NY][LR_NX], D[LR_NY][LR_NU];
    double Rp1, Rp3;                                     /* the instantaneous port terms y = y0 + R u_port */
    LrZener z;                                           /* the zener pair at node d (its R11 the port's self term) */
    double x[LR_NX], jprev;
} LinRet;

void* cr_ret_new(double fs, int level)
{
    LinRet* r = calloc(1, sizeof *r);
    if (!r) return NULL;
    const double (*A)[4] = level ? LR_A1 : LR_A0, (*B)[4] = level ? LR_B1 : LR_B0;
    const double (*C)[4] = level ? LR_C1 : LR_C0, (*D)[4] = level ? LR_D1 : LR_D0;
    const int n = LR_NX, nu = LR_NU, N = n + 2 * nu;
    const double T = 1.0 / fs;
    double Z[144] = { 0 }, E[144];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) Z[i * N + j] = A[i][j] * T;
        for (int j = 0; j < nu; j++) Z[i * N + n + j] = B[i][j] * T;
    }
    for (int j = 0; j < nu; j++) Z[(n + j) * N + n + nu + j] = 1.0;
    expm(N, Z, E);
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) r->Phi[i][j] = E[i * N + j];
        const double F1j = E[i * N + n], F2j = E[i * N + n + nu];
        r->G1[i][0] = F2j; r->G0j[i] = F1j - F2j;                    /* the jack: first-order hold */
        for (int j = 1; j < nu; j++) r->G1[i][j] = E[i * N + n + j];  /* the ports: held at their new value */
    }
    memcpy(r->Cy, C, sizeof r->Cy); memcpy(r->D, D, sizeof r->D);
    double Rm[LR_NY][LR_NU];
    for (int a = 0; a < LR_NY; a++) for (int b = 0; b < nu; b++) {
        double s = D[a][b]; for (int l = 0; l < n; l++) s += C[a][l] * r->G1[l][b]; Rm[a][b] = s;
    }
    /* Rm = D + Cy G1: each output's instantaneous response to an input held over the step.
     * rows: o2 0, d 1, n 2, p1 3; columns: vin 0, iz 1, (in 2, unused), ip 3. Node d must not see p1 within a step */
    if (fabs(Rm[1][3]) > 1e-9 * fabs(Rm[1][1]) || !(Rm[3][3] > 0.0) || !(Rm[1][1] > 0.0)) { free(r); return NULL; }
    r->z.R11 = Rm[1][1]; r->Rp1 = Rm[3][1]; r->Rp3 = Rm[3][3];
    zener_pair_table(&r->z);
    zener_uniform(&r->z);
    cr_ret_reset(r);
    return r;
}

int cr_ret_reset(void* rv)
{
    LinRet* r = rv;
    for (int i = 0; i < LR_NX; i++) r->x[i] = 0.0;   /* the DC point with the jack at 0: every node at VREF */
    r->jprev = 0.0;
    return 0;
}

double cr_ret_tick(void* rv, double jack)
{
    LinRet* r = rv;
    double xp[LR_NX];
    for (int i = 0; i < LR_NX; i++) {
        double a = r->G0j[i] * r->jprev + r->G1[i][0] * jack;
        for (int j = 0; j < LR_NX; j++) a += r->Phi[i][j] * r->x[j];
        xp[i] = a;
    }
    double vd0 = r->D[1][0] * jack, vp0 = r->D[3][0] * jack;
    for (int l = 0; l < LR_NX; l++) { vd0 += r->Cy[1][l] * xp[l]; vp0 += r->Cy[3][l] * xp[l]; }
    /* the zener pair: its current from node d's open-circuit value */
    const double iz = -zener_i(&r->z, vd0);
    /* the swing limit on the pole node, from its open-circuit value: explicit */
    const double pq = vp0 + r->Rp1 * iz;
    const double ip = pq > LR_VP ? (LR_VP - pq) / r->Rp3 : pq < -LR_VP ? (-LR_VP - pq) / r->Rp3 : 0.0;
    for (int i = 0; i < LR_NX; i++) r->x[i] = xp[i] + r->G1[i][1] * iz + r->G1[i][3] * ip;
    r->jprev = jack;
    double o = r->D[0][0] * jack + r->D[0][1] * iz + r->D[0][3] * ip;
    for (int l = 0; l < LR_NX; l++) o += r->Cy[0][l] * r->x[l];
    return o;
}

long cr_ret_nonconv(void* r) { (void)r; return 0; }   /* explicit: nothing to converge */
